#!/usr/bin/env node
// Records the slice goldens (test/goldens/slices.json) from a released runtime that speaks protocol v1
// (v0.1.0): the plates of test/conformance/plates.ts sliced by that release's own host and engine, on both
// variants, in Node worker threads. The v2 host must give the same G-code (the conformance suite checks),
// the "; generated by" line aside.
//
//   node tools/goldens/record-slices-v1.mjs <runtime folder of muon3d-slicer-engine-0.1.0.tgz>
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { Worker } from 'node:worker_threads';
import { PLATES, comparable } from '../../test/conformance/plates.ts';

const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const runtime = process.argv[2];
if (!runtime) {
  console.error('usage: node tools/goldens/record-slices-v1.mjs <runtime folder>');
  process.exit(2);
}
const manifest = JSON.parse(fs.readFileSync(path.join(runtime, 'manifest.json'), 'utf8'));
if (manifest.host.protocol !== 1) throw new Error(`${runtime} speaks protocol ${manifest.host.protocol}, not 1`);

// The v1 host installs its message loop where it finds a worker global scope; this provides one on top of
// worker_threads (examples/node-cli/host-thread.mjs of v0.1.0).
const thread = `
import { parentPort, workerData } from 'node:worker_threads';
globalThis.postMessage = (message, transfer) => parentPort.postMessage(message, transfer);
globalThis.WorkerGlobalScope = class WorkerGlobalScope {};
await import(workerData.hostUrl);
delete globalThis.WorkerGlobalScope;
parentPort.on('message', (data) => globalThis.onmessage?.({ data }));
`;

function sliceAll(variant) {
  return new Promise((resolve, reject) => {
    const worker = new Worker(new URL(`data:text/javascript,${encodeURIComponent(thread)}`), {
      workerData: { hostUrl: pathToFileURL(path.join(runtime, manifest.host.file)).href },
    });
    const results = {};
    let next = 0;
    const send = () => {
      const plate = PLATES[next];
      const params = plate.params();
      const job = { ...params.configs, objects: params.objects.map((o) => ({ name: o.name, positions: o.mesh.positions, ...(o.config ? { config: o.config } : {}) })), toolpaths: false };
      worker.postMessage({ type: 'slice', id: plate.id, job });
    };
    worker.on('error', reject);
    worker.on('message', (m) => {
      if (m.type === 'ready') send();
      else if (m.type === 'fatal' || m.type === 'failed') reject(new Error(`${variant}: ${m.message ?? m.error?.message}`));
      else if (m.type === 'sliced') {
        const text = comparable(m.output.gcode);
        const { stats } = m.output;
        results[m.id] = {
          sha256: createHash('sha256').update(text).digest('hex'),
          bytes: m.output.gcode.length,
          layers: stats.layers,
          printTimeText: stats.printTimeText,
          filamentMm: stats.filamentMm,
        };
        if (++next < PLATES.length) send();
        else void worker.terminate().then(() => resolve(results));
      }
    });
    worker.postMessage({ type: 'init', baseUrl: pathToFileURL(runtime + path.sep).href, variant });
  });
}

const plates = {};
for (const variant of ['st', 'mt']) {
  const results = await sliceAll(variant);
  for (const [id, r] of Object.entries(results)) (plates[id] ??= {})[variant] = r;
  console.log(`${variant}: ${Object.keys(results).length} plates`);
}
const out = path.join(repo, 'test/goldens/slices.json');
const reference = {
  version: manifest.version,
  // The goldens hold only for an engine built from this Orca commit (the upstream canary builds others).
  orcaCommit: manifest.orcaCommit,
  host: manifest.host.sha256,
  wasm: { st: manifest.variants.st.sha256.wasm, mt: manifest.variants.mt.sha256.wasm },
};
fs.writeFileSync(out, JSON.stringify({ format: 1, reference, plates }, null, 1) + '\n');
console.log(`OK: ${out}`);
